      "claims": ["c1", "c2"]
    },
    {
      "term": "глубина проникновения",
      "term_en": "invasion depth",
      "abbr": "",
      "definition": "Расстояние от стенки скважины, на которое фильтрат раствора вошёл в пласт и изменил его.",
      "claims": ["c2", "c5"]
    },
    {
      "term": "глубинность метода",
      "term_en": "depth of investigation",
      "abbr": "",
      "definition": "Расстояние от скважины, на которое метод ещё получает сигнал от породы. Одни методы видят глубоко, другие — только ближнюю зону.",
      "claims": ["c5", "c6"]
    },
    {
      "term": "вертикальная разрешающая способность",
      "term_en": "vertical resolution",
      "abbr": "",
      "definition": "Способность метода различать тонкие слои по вертикали. Высокая разрешающая способность позволяет видеть тонкие прослои.",
      "claims": ["c3"]
    },
    {
      "term": "электрометрия",
      "term_en": "electrical logging",
      "abbr": "",
      "definition": "Группа методов ГИС, которые измеряют электрические свойства пород, например сопротивление.",
      "claims": ["c3", "c5"]
    },
    {
      "term": "неизменённая часть пласта",
      "term_en": "uninvaded zone",
      "abbr": "",
      "definition": "Часть пласта за пределами зоны проникновения, куда фильтрат раствора не дошёл. Она сохраняет исходные свойства породы.",
      "claims": ["c3"]
    }
  ],
